command -v vi >/dev/null || { echo 'Install vi first.' >&2; exit 1; }
root="$HOME/.local/share/dft-tddft"
target="$root/v1.0.3"
mkdir -p -- "$root"
if [[ ! -f "$target/activate" ]]; then (
stage=$(mktemp -d "$root/.install.XXXXXXXX")
trap 'if [[ -d "$stage" ]]; then rm -r -- "$stage"; fi' EXIT
