python3 - "$stage" "$target" <<'TDDFT_INSTALL'
import os
from pathlib import Path
import sys
source, target = map(Path, sys.argv[1:])
if os.path.lexists(target):
    if target.is_symlink() or not (target / "activate").is_file():
        raise SystemExit("Install destination exists and is incomplete: " + str(target))
else:
    os.rename(source, target)
TDDFT_INSTALL
); fi
if [[ -L "$target" || ! -f "$target/activate" ]]; then echo 'Invalid installation.' >&2; exit 1; fi
if ( : </dev/tty ) 2>/dev/null; then
    bash --rcfile "$target/activate" -i </dev/tty
else
    printf 'Open lesson: bash --rcfile %q -i\n' "$target/activate"
fi
